// own2.cpp (K39) -- a second chess solver for kings + pawns + up to TWO officers, flat or cylinder board, with the double
// step and en passant, an officer cap (total and per colour) and per-colour promotion sets. Written by K39 from
// kings/SPEC.md; it reuses the geometry helpers of K39's own39.cpp (itself from the K27 referee's ownchess.cpp) and shares
// no code with kpsolve.c. Unlike own39 it never builds a state list or an edge list: a layer is solved by counting
// retrograde analysis with predecessors generated by un-moves (kings and officers, non-capturing), so a layer costs
// two bytes per state.
// Model: a promotion is *capped* if the position after it holds more than CAP officers, or more than CAPW (CAPB) officers
// of the promoter's colour. Bound A: a capped promotion is an immediate White win; bound B: an immediate Black win.
// Restricting a side (its promotion set, its per-colour cap) can only lower that side's value, so bound A with Black
// restricted is still an upper bound of the true value, and bound B with White restricted a lower bound.
// Usage: own2 W H CYL BOUND CAP CAPW CAPB PROMW PROMB MOVES < positions   (PROMW, PROMB: subsets of QRBN)
//   -> "<pos> | X" (W/D/L/X, White's view, the chosen bound) [" | mv:v ..."]
#include <cstdio>
#include <cstdlib>
#include <cstdint>
#include <cstring>
#include <cctype>
#include <iostream>
#include <map>
#include <sstream>
#include <string>
#include <vector>
using std::string; using std::vector;
typedef unsigned long long u64;
static int W = 7, H = 6, N = 42, CYL = 0, BOUND = 0, CAP = 2, CAPC[2] = {2, 2}, MOVES = 0;
static vector<int> PROM[2];
static inline int fl(int s) { return s % W; }
static inline int rk(int s) { return s / W; }
static inline int sqat(int x, int y) {
  if (y < 0 || y >= H) return -1;
  if (CYL) x = ((x % W) + W) % W; else if (x < 0 || x >= W) return -1;
  return y * W + x;
}
static inline bool kadj(int a, int b) {
  if (a == b) return false;
  int df = abs(fl(a) - fl(b)); if (CYL && W - df < df) df = W - df;
  return df <= 1 && abs(rk(a) - rk(b)) <= 1;
}
static const int DF[8] = {1, -1, 0, 0, 1, 1, -1, -1}, DR[8] = {0, 0, 1, -1, 1, -1, 1, -1};
static const int KDF[8] = {1, 2, 2, 1, -1, -2, -2, -1}, KDR[8] = {2, 1, -1, -2, -2, -1, 1, 2};
// officer code: type (0..3 = Q R B N) + 4 * colour
struct Pos { int wk, bk; u64 wp, bp; int no; int oc[2], os[2]; int ep; };
struct Key {
  u64 wp, bp; int no, c0, c1, ep;   // officer codes sorted (c0 <= c1), unused = -1
  bool operator<(const Key& o) const {
    if (wp != o.wp) return wp < o.wp; if (bp != o.bp) return bp < o.bp; if (no != o.no) return no < o.no;
    if (c0 != o.c0) return c0 < o.c0; if (c1 != o.c1) return c1 < o.c1; return ep < o.ep; }
  bool operator==(const Key& o) const { return wp == o.wp && bp == o.bp && no == o.no && c0 == o.c0 && c1 == o.c1 && ep == o.ep; }
};
static void norm(Pos& p) {  // canonical officer order: by code, then by square
  if (p.no == 2 && (p.oc[0] > p.oc[1] || (p.oc[0] == p.oc[1] && p.os[0] > p.os[1]))) {
    std::swap(p.oc[0], p.oc[1]); std::swap(p.os[0], p.os[1]);
  }
}
static Key keyOf(const Pos& p) { return Key{p.wp, p.bp, p.no, p.no > 0 ? p.oc[0] : -1, p.no > 1 ? p.oc[1] : -1, p.ep}; }
static inline u64 occOf(const Pos& p) {
  u64 o = p.wp | p.bp | (1ULL << p.wk) | (1ULL << p.bk);
  for (int j = 0; j < p.no; j++) o |= 1ULL << p.os[j];
  return o;
}
static bool reach(int ty, int o, int s, u64 occ) {
  if (ty == 3) { for (int i = 0; i < 8; i++) if (sqat(fl(o) + KDF[i], rk(o) + KDR[i]) == s) return true; return false; }
  int lo = ty == 2 ? 4 : 0, hi = ty == 1 ? 4 : 8;
  for (int i = lo; i < hi; i++) {
    int x = fl(o), y = rk(o);
    for (;;) {
      x += DF[i]; y += DR[i];
      int q = sqat(x, y);
      if (q < 0 || q == o) break;
      if (q == s) return true;
      if (occ >> q & 1) break;
    }
  }
  return false;
}
static bool pawnAtt(u64 pp, int s, int c) {
  int pr = c == 0 ? rk(s) - 1 : rk(s) + 1;
  for (int d = -1; d <= 1; d += 2) { int q = sqat(fl(s) + d, pr); if (q >= 0 && (pp >> q & 1)) return true; }
  return false;
}
static bool attacked(const Pos& p, int s, int c) {
  if (kadj(c == 0 ? p.wk : p.bk, s)) return true;
  if (pawnAtt(c == 0 ? p.wp : p.bp, s, c)) return true;
  u64 occ = occOf(p);
  for (int j = 0; j < p.no; j++)
    if ((p.oc[j] >> 2) == c && p.os[j] != s && reach(p.oc[j] & 3, p.os[j], s, occ)) return true;
  return false;
}
// destinations of a king/officer step set from square o (non-capturing and capturing alike), deduplicated
static u64 dests(int ty, int o, u64 occ) {  // ty: 0..3 officer, 4 king
  u64 d = 0;
  if (ty == 4) { for (int i = 0; i < 8; i++) { int t = sqat(fl(o) + DF[i], rk(o) + DR[i]); if (t >= 0 && t != o) d |= 1ULL << t; } return d; }
  if (ty == 3) { for (int i = 0; i < 8; i++) { int t = sqat(fl(o) + KDF[i], rk(o) + KDR[i]); if (t >= 0 && t != o) d |= 1ULL << t; } return d; }
  int lo = ty == 2 ? 4 : 0, hi = ty == 1 ? 4 : 8;
  for (int i = lo; i < hi; i++) {
    int x = fl(o), y = rk(o);
    for (;;) {
      x += DF[i]; y += DR[i];
      int q = sqat(x, y);
      if (q < 0 || q == o) break;
      d |= 1ULL << q;
      if (occ >> q & 1) break;
    }
  }
  return d;
}
struct Move { Pos to; bool capped; int pc, from, dest, pty; };
static void removeOff(Pos& n, int j) { if (j == 0 && n.no == 2) { n.oc[0] = n.oc[1]; n.os[0] = n.os[1]; } n.no--; }
// remove an enemy (colour e) piece standing on t (pawn or officer); returns true if something was captured
static bool captureAt(Pos& n, int t, int e) {
  u64& pp = e == 0 ? n.wp : n.bp;
  if (pp >> t & 1) { pp &= ~(1ULL << t); return true; }
  for (int j = 0; j < n.no; j++) if (n.os[j] == t && (n.oc[j] >> 2) == e) { removeOff(n, j); return true; }
  return false;
}
static void gen(const Pos& p, int c, vector<Move>& out) {
  out.clear();
  u64 occ = occOf(p);
  u64 ownAll = (c == 0 ? p.wp : p.bp) | (1ULL << (c == 0 ? p.wk : p.bk));
  for (int j = 0; j < p.no; j++) if ((p.oc[j] >> 2) == c) ownAll |= 1ULL << p.os[j];
  int ek = c == 0 ? p.bk : p.wk;
  auto push = [&](Pos n, bool capped, int pc, int from, int dest, int pty) {
    if (!capped) { norm(n); if (attacked(n, c == 0 ? n.wk : n.bk, 1 - c)) return; }
    Move m; m.to = n; m.capped = capped; m.pc = pc; m.from = from; m.dest = dest; m.pty = pty;
    out.push_back(m);
  };
  // king
  int k = c == 0 ? p.wk : p.bk;
  u64 d = dests(4, k, occ) & ~ownAll & ~(1ULL << ek);
  for (int t = 0; t < N; t++) if (d >> t & 1) {
    Pos n = p; n.ep = -1;
    captureAt(n, t, 1 - c);
    if (c == 0) n.wk = t; else n.bk = t;
    push(n, false, 'K', k, t, -1);
  }
  // officers
  for (int j = 0; j < p.no; j++) {
    if ((p.oc[j] >> 2) != c) continue;
    int o = p.os[j], ty = p.oc[j] & 3;
    u64 dd = dests(ty, o, occ) & ~ownAll & ~(1ULL << ek);
    for (int t = 0; t < N; t++) if (dd >> t & 1) {
      Pos n = p; n.ep = -1;
      int jj = j;
      // capture first (it may shift the officer array)
      for (int i = 0; i < n.no; i++) if (n.os[i] == t && (n.oc[i] >> 2) != c) { removeOff(n, i); if (i < jj) jj--; break; }
      u64& qq = c == 0 ? n.bp : n.wp; qq &= ~(1ULL << t);
      n.os[jj] = t;
      push(n, false, "QRBN"[ty], o, t, -1);
    }
  }
  // pawns
  u64 own = c == 0 ? p.wp : p.bp, opp = c == 0 ? p.bp : p.wp;
  int dir = c == 0 ? 1 : -1, last = c == 0 ? H - 1 : 0, second = c == 0 ? 1 : H - 2;
  for (int s = 0; s < N; s++) {
    if (!(own >> s & 1)) continue;
    int f = fl(s), r = rk(s), r1 = r + dir;
    auto addpawn = [&](int t, int capsq) {
      Pos n = p; n.ep = -1;
      (c == 0 ? n.wp : n.bp) &= ~(1ULL << s);
      if (capsq >= 0) captureAt(n, capsq, 1 - c);
      if (r1 == last) {
        // legality first (the new piece of any type stands on t; it may block a check): model it as an own pawn
        Pos chk = n; (c == 0 ? chk.wp : chk.bp) |= 1ULL << t;
        if (attacked(chk, c == 0 ? chk.wk : chk.bk, 1 - c)) return;
        int mine = 0; for (int j = 0; j < n.no; j++) mine += (n.oc[j] >> 2) == c;
        for (int ty : PROM[c]) {
          if (n.no + 1 > CAP || mine + 1 > CAPC[c]) { push(n, true, 'P', s, t, ty); continue; }
          Pos m = n; m.oc[m.no] = ty + 4 * c; m.os[m.no] = t; m.no++;
          push(m, false, 'P', s, t, ty);
        }
      } else { (c == 0 ? n.wp : n.bp) |= 1ULL << t; push(n, false, 'P', s, t, -1); }
    };
    int t = sqat(f, r1);
    if (!(occ >> t & 1)) {
      addpawn(t, -1);
      if (r == second) {
        int t2 = sqat(f, r1 + dir);
        if (t2 >= 0 && rk(t2) != last && !(occ >> t2 & 1)) {
          Pos n = p; n.ep = -1;
          if (c == 0) n.wp = (n.wp & ~(1ULL << s)) | (1ULL << t2); else n.bp = (n.bp & ~(1ULL << s)) | (1ULL << t2);
          if (pawnAtt(opp, t, 1 - c)) n.ep = t;
          push(n, false, 'P', s, t2, -1);
        }
      }
    }
    u64 seen = 0;
    for (int dd = -1; dd <= 1; dd += 2) {
      int q = sqat(f + dd, r1);
      if (q < 0 || (seen >> q & 1)) continue;
      seen |= 1ULL << q;
      bool enemyOff = false;
      for (int j = 0; j < p.no; j++) if (p.os[j] == q && (p.oc[j] >> 2) != c) enemyOff = true;
      if ((opp >> q & 1) || enemyOff) addpawn(q, q);
      else if (p.ep == q && !(occ >> q & 1)) { int vs = sqat(fl(q), r); if (opp >> vs & 1) addpawn(q, vs); }
    }
  }
}
// ---- layers: value per state, 0 draw/unknown, 1 mover wins, 2 mover loses, 3 illegal
struct Layer { vector<uint8_t> v; };
static std::map<Key, Layer*> memo;
static long nlayers = 0; static long long nstates = 0;
static inline size_t lsize(int no) { size_t s = 2; for (int i = 0; i < 2 + no; i++) s *= N; return s; }
static inline size_t sidx(const Pos& p, int stm) {
  size_t i = (size_t)p.wk * N + p.bk;
  for (int j = 0; j < p.no; j++) i = i * N + p.os[j];
  return i * 2 + stm;
}
static Layer* solve(const Key& k);
static Key ckey[256]; static Layer* cval[256];  // a small direct-mapped cache in front of the map
static Layer* getLayer(const Key& k) {
  unsigned h = (unsigned)((k.wp * 0x9E3779B97F4A7C15ULL ^ (k.bp + 7) * 0xC2B2AE3D27D4EB4FULL ^ (u64)(k.c0 + 3 + 16 * (k.c1 + 3) + 512 * (k.ep + 2))) >> 56);
  if (cval[h] && ckey[h] == k) return cval[h];
  auto it = memo.find(k);
  Layer* L = it != memo.end() ? it->second : solve(k);
  ckey[h] = k; cval[h] = L;
  return L;
}
static int moveValue(const Move& m, int c, const Key* self) {  // for the opponent: 1 wins, 2 loses, 0 draw; -1 in-layer
  if (m.capped) { bool whiteWins = BOUND == 0; return ((c == 0) == whiteWins) ? 2 : 1; }
  Key ck = keyOf(m.to);
  if (self && ck == *self) return -1;
  uint8_t v = getLayer(ck)->v[sidx(m.to, 1 - c)];
  if (v == 3) { fprintf(stderr, "own2: internal error: illegal child\n"); exit(1); }
  return v;
}
static bool decode(const Key& k, size_t idx, Pos& p, int& stm) {
  stm = idx % 2; idx /= 2;
  p.wp = k.wp; p.bp = k.bp; p.no = k.no; p.ep = k.ep;
  if (k.no > 0) p.oc[0] = k.c0; if (k.no > 1) p.oc[1] = k.c1;
  for (int j = k.no - 1; j >= 0; j--) { p.os[j] = idx % N; idx /= N; }
  p.bk = idx % N; idx /= N; p.wk = (int)idx;
  u64 pw = p.wp | p.bp;
  if (p.wk == p.bk || (pw >> p.wk & 1) || (pw >> p.bk & 1) || kadj(p.wk, p.bk)) return false;
  u64 seen = pw | (1ULL << p.wk) | (1ULL << p.bk);
  for (int j = 0; j < p.no; j++) { if (seen >> p.os[j] & 1) return false; seen |= 1ULL << p.os[j]; }
  if (p.no == 2 && p.oc[0] == p.oc[1] && p.os[0] > p.os[1]) return false;  // canonical order of equal officers
  if (k.ep >= 0 && stm != (rk(k.ep) == 2 ? 1 : 0)) return false;
  if (attacked(p, stm == 0 ? p.bk : p.wk, stm)) return false;  // the side not to move is in check
  return true;
}
static Layer* solve(const Key& key) {
  Layer* L = new Layer();
  size_t n = lsize(key.no);
  L->v.assign(n, 3);
  memo[key] = L;
  nlayers++;
  vector<uint8_t> cnt(n, 0);
  vector<size_t> q;
  vector<Move> mv;
  for (size_t i = 0; i < n; i++) {
    Pos p; int c;
    if (!decode(key, i, p, c)) continue;
    nstates++;
    gen(p, c, mv);
    if (mv.empty()) { L->v[i] = attacked(p, c == 0 ? p.wk : p.bk, 1 - c) ? 2 : 0; if (L->v[i] == 2) q.push_back(i); continue; }
    int pending = 0; bool win = false, drawExit = false;
    for (auto& m : mv) {
      int cv = moveValue(m, c, &key);
      if (cv < 0) pending++;
      else if (cv == 2) { win = true; break; }
      else if (cv == 0) drawExit = true;
    }
    if (win) { L->v[i] = 1; q.push_back(i); continue; }
    L->v[i] = 0;
    if (!pending && !drawExit) { L->v[i] = 2; q.push_back(i); continue; }
    cnt[i] = drawExit ? 255 : (uint8_t)pending;   // 255: never lost (a drawn exit)
    if (pending > 250) { fprintf(stderr, "own2: too many moves\n"); exit(1); }
  }
  // un-moves: for a decided state t (side c to move), the previous mover was 1-c and moved a king or an officer
  // without capturing (the only in-layer moves); its piece now stands on x and came from an empty square y.
  for (size_t h = 0; h < q.size(); h++) {
    size_t t = q[h];
    Pos p; int c;
    decode(key, t, p, c);
    int pm = 1 - c;
    u64 occ = occOf(p);
    uint8_t vt = L->v[t];
    auto visit = [&](Pos& pr) {
      norm(pr);
      // the predecessor must be legal with pm to move: c (not to move) not in check
      if (pr.wk == pr.bk || kadj(pr.wk, pr.bk)) return;
      if (attacked(pr, c == 0 ? pr.wk : pr.bk, pm)) return;
      size_t s = sidx(pr, pm);
      if (L->v[s] != 0) return;
      if (vt == 2) { L->v[s] = 1; q.push_back(s); }
      else if (cnt[s] != 255 && --cnt[s] == 0) { L->v[s] = 2; q.push_back(s); }
    };
    if (key.ep >= 0) continue;  // e.p. layers have no in-layer moves
    int kx = pm == 0 ? p.wk : p.bk;
    u64 dk = dests(4, kx, occ) & ~occ;
    for (int y = 0; y < N; y++) if (dk >> y & 1) { Pos pr = p; if (pm == 0) pr.wk = y; else pr.bk = y; visit(pr); }
    for (int j = 0; j < p.no; j++) {
      if ((p.oc[j] >> 2) != pm) continue;
      u64 dd = dests(p.oc[j] & 3, p.os[j], occ) & ~occ;
      for (int y = 0; y < N; y++) if (dd >> y & 1) { Pos pr = p; pr.os[j] = y; visit(pr); }
    }
  }
  return L;
}
static int sqparse(const string& t, size_t off) {
  if (t.size() < off + 2) return -1;
  int f = t[off] - 'a', r = atoi(t.c_str() + off + 1) - 1;
  if (f < 0 || f >= W || r < 0 || r >= H) return -1;
  return r * W + f;
}
static bool parsepos(const string& line, Pos& p, int& stm) {
  std::istringstream is(line); vector<string> t; string x; while (is >> x) t.push_back(x);
  if (t.size() < 4) return false;
  p.wk = p.bk = -1; p.wp = p.bp = 0; p.no = 0; p.ep = -1;
  for (size_t i = 0; i + 2 < t.size(); i++) {
    char c = t[i][0]; int s = sqparse(t[i], 1); if (s < 0) return false;
    if (c == 'K') p.wk = s; else if (c == 'k') p.bk = s; else if (c == 'P') p.wp |= 1ULL << s; else if (c == 'p') p.bp |= 1ULL << s;
    else { const char* tl = strchr("QRBN", toupper(c)); if (!tl || p.no >= 2) return false; p.oc[p.no] = (int)(tl - "QRBN") + 4 * (isupper(c) ? 0 : 1); p.os[p.no] = s; p.no++; }
  }
  stm = t[t.size() - 2] == "b";
  if (t.back() != "-") { int e = sqparse(t.back(), 0); if (e < 0) return false; if (pawnAtt(stm == 0 ? p.wp : p.bp, e, stm)) p.ep = e; }
  norm(p);
  return true;
}
static string sqn(int s) { char b[8]; snprintf(b, sizeof b, "%c%d", 'a' + fl(s), rk(s) + 1); return b; }
int main(int argc, char** argv) {
  if (argc < 11) { fprintf(stderr, "usage: own2 W H CYL BOUND CAP CAPW CAPB PROMW PROMB MOVES\n"); return 2; }
  W = atoi(argv[1]); H = atoi(argv[2]); N = W * H; CYL = atoi(argv[3]); BOUND = atoi(argv[4]); CAP = atoi(argv[5]);
  CAPC[0] = atoi(argv[6]); CAPC[1] = atoi(argv[7]); MOVES = atoi(argv[10]);
  for (int c = 0; c < 2; c++) for (const char* s = argv[8 + c]; *s; s++) PROM[c].push_back((int)(strchr("QRBN", *s) - "QRBN"));
  if (N > 64 || H < 5 || CAP > 2) { fprintf(stderr, "own2: need W*H <= 64, H >= 5, CAP <= 2\n"); return 2; }
  string line; vector<Move> mv;
  while (std::getline(std::cin, line)) {
    if (line.empty() || line[0] == '#') { puts(line.c_str()); continue; }
    Pos p; int stm;
    if (!parsepos(line, p, stm) || p.no > CAP) { printf("%s | bad\n", line.c_str()); continue; }
    Pos d; int ds;
    size_t ix = sidx(p, stm);
    Layer* L = getLayer(keyOf(p));
    bool ok = decode(keyOf(p), ix, d, ds);
    uint8_t v = ok ? L->v[ix] : 3;
    char r = v == 3 ? 'X' : v == 0 ? 'D' : ((v == 1) == (stm == 0)) ? 'W' : 'L';
    printf("%s | %c", line.c_str(), r);
    if (MOVES && v != 3) {
      gen(p, stm, mv);
      printf(" |");
      for (auto& m : mv) {
        int cv = moveValue(m, stm, nullptr);
        char ch = cv == 0 ? 'D' : ((cv == 1) == (stm == 1)) ? 'W' : 'L';
        printf(" %c%s%s", m.pc, sqn(m.from).c_str(), sqn(m.dest).c_str());
        if (m.pty >= 0) printf("=%c", "QRBN"[m.pty]);
        printf(":%c", ch);
      }
    }
    printf("\n"); fflush(stdout);
  }
  fprintf(stderr, "[own2 %s %dx%d bound %c cap %d capw %d capb %d: layers %ld, states %lld]\n", CYL ? "cyl" : "flat", W, H, BOUND ? 'B' : 'A', CAP, CAPC[0], CAPC[1], nlayers, nstates);
  return 0;
}
